// Reuniones que ya terminaron (hace 10+ min) y tienen transcripción de Meet adjunta al evento.
const eventos = $input.first().json.items || [];
const limite = Date.now() - 10 * 60 * 1000;
const lista = [];

for (const ev of eventos) {
  if (ev.status === 'cancelled' || !ev.end?.dateTime) continue;
  if (new Date(ev.end.dateTime).getTime() > limite) continue;
  const doc = (ev.attachments || []).find(
    (a) => a.mimeType === 'application/vnd.google-apps.document' && /transcri/i.test(a.title || '')
  );
  if (!doc?.fileId) continue;
  lista.push({
    calendar_id: ev.id,
    titulo: ev.summary || 'Sin título',
    inicio: ev.start.dateTime,
    fin: ev.end.dateTime,
    doc_id: doc.fileId,
    asistentes: (ev.attendees || []).filter((a) => !a.resource).map((a) => a.email),
  });
}

if (!lista.length) return [];
return [{ json: { eventos: lista } }];

// Descarta las reuniones que Nexo ya tiene guardadas. Máximo 5 por corrida.
const hechas = new Set($input.first().json.hechas || []);
const eventos = $('Reuniones con transcripción').first().json.eventos;
return eventos
  .filter((e) => !hechas.has(e.calendar_id))
  .slice(0, 5)
  .map((e) => ({ json: e }));

// Mide cuánto habló cada persona a partir del texto de la transcripción de Meet.
// Formato de Meet: líneas "Nombre Apellido: lo que dijo" separadas por marcas de tiempo "00:05:12".
const ctx = $('Contexto de Nexo').first().json;
const eventos = $('Pendientes').all();
const salida = [];

$input.all().forEach((it, i) => {
  const ev = eventos[i]?.json;
  const bruto = String(it.json.texto || '');
  if (!ev || !bruto.trim()) return; // sin permiso para leer el Doc o transcripción vacía

  const conteo = {};
  const limpias = [];
  let anterior = null;
  for (const linea of bruto.split(/\r?\n/)) {
    const l = linea.trim();
    if (!l || /^\d{1,2}:\d{2}(:\d{2})?$/.test(l)) continue; // marcas de tiempo
    const m = l.match(/^([^:\d][^:]{1,60}):\s+(.+)$/);
    if (m && !/https?$/i.test(m[1])) {
      const nombre = m[1].trim();
      const palabras = m[2].split(/\s+/).filter(Boolean).length;
      conteo[nombre] ??= { nombre, palabras: 0, intervenciones: 0 };
      conteo[nombre].palabras += palabras;
      if (anterior !== nombre) conteo[nombre].intervenciones += 1;
      anterior = nombre;
      limpias.push(`${nombre}: ${m[2]}`);
    } else if (limpias.length) {
      limpias.push(l); // continuación o encabezado
    }
  }
  const total = Object.values(conteo).reduce((t, p) => t + p.palabras, 0);
  if (!total) return;
  const participacion = Object.values(conteo)
    .map((p) => ({ ...p, pct_voz: Math.round((p.palabras / total) * 1000) / 10 }))
    .sort((a, b) => b.palabras - a.palabras);

  let texto = limpias.join('\n');
  if (texto.length > 150000) texto = texto.slice(0, 150000) + '\n[transcripción recortada]';

  salida.push({
    json: {
      evento: ev,
      participacion,
      hablantes: participacion.map((p) => p.nombre).join(', '),
      texto,
      personas: JSON.stringify(ctx.personas),
      proyectos: JSON.stringify(ctx.proyectos),
      compromisos_abiertos: JSON.stringify(ctx.compromisos_abiertos),
    },
    pairedItem: i,
  });
});

return salida;

parameters.text:
=Eres el analista de reuniones del área de Desarrollo de Software. Analiza la transcripción de una reunión de Google Meet y devuelve SOLO un objeto JSON válido, sin texto antes ni después y sin bloques de código.

Reunión: {{ $json.evento.titulo }}
Fecha y hora de la reunión: {{ $json.evento.inicio }}
Personas del equipo registradas en Nexo: {{ $json.personas }}
Proyectos activos (usa el valor exacto de "proyecto"): {{ $json.proyectos }}
Compromisos abiertos de reuniones anteriores: {{ $json.compromisos_abiertos }}
Hablantes detectados en la transcripción: {{ $json.hablantes }}

Formato de respuesta:
{
  "proyecto": "nombre exacto de un proyecto de la lista, o null si la reunión no es de un proyecto específico",
  "resumen": "3 a 5 frases: de qué se habló, avances con cifras, problemas y decisiones",
  "acuerdos": ["una decisión por elemento"],
  "cita": "la frase textual más representativa, tal como se dijo",
  "compromisos": [
    { "responsable": "nombre como aparece en la transcripción", "descripcion": "qué va a hacer", "fecha_limite": "YYYY-MM-DD o null" }
  ],
  "compromisos_cumplidos": [1, 2],
  "personas": [
    { "nombre": "nombre como aparece en la transcripción", "actualizacion_completa": true, "menciono_bloqueo": false, "observacion": "1 o 2 frases" }
  ]
}

Reglas:
- "compromisos_cumplidos" lleva los id de la lista de compromisos abiertos que en esta reunión se reportaron como terminados. Si no hay, usa [].
- "personas" incluye solo a hablantes que son del equipo (no clientes ni externos).
- "actualizacion_completa": true si al reportar su trabajo dio estatus, al menos un dato concreto (porcentaje, cantidad o fecha) y el siguiente paso; false si le faltó alguno; null si no reportó avance en esta reunión.
- "menciono_bloqueo": true solo si comunicó un impedimento de su propio trabajo.
- "observacion": describe hechos observables (qué reportó, si dio datos, si cerró con siguiente paso, si comunicó un bloqueo). No juzgues personalidad, tono, acento, seguridad al hablar ni capacidad. Si habló poco, dilo como hecho, sin valorarlo.
- Convierte fechas relativas ("el viernes", "mañana") a YYYY-MM-DD usando la fecha de la reunión.
- No inventes nada que no esté en la transcripción. Escribe en español.

Transcripción:
{{ $json.texto }}

