// Une la medición por código con el análisis de la IA y arma lo que se guarda en Nexo.
const base = $('Medir participación').all();

function leerJSON(t) {
  const s = String(t || '').replace(/```(json)?/gi, '');
  const ini = s.indexOf('{');
  const fin = s.lastIndexOf('}');
  if (ini < 0 || fin < ini) throw new Error('La IA no devolvió JSON: ' + s.slice(0, 200));
  return JSON.parse(s.slice(ini, fin + 1));
}
const lista = (v) => (Array.isArray(v) ? v : []);

return $input.all().map((it, i) => {
  const b = base[i].json;
  const ia = leerJSON(it.json.text);
  const abiertos = new Set(JSON.parse(b.compromisos_abiertos || '[]').map((c) => c.id));
  return {
    json: {
      titulo: b.evento.titulo,
      payload: {
        evento: b.evento,
        proyecto: ia.proyecto || null,
        resumen: String(ia.resumen || ''),
        acuerdos: lista(ia.acuerdos).map(String),
        cita: String(ia.cita || ''),
        participacion: b.participacion,
        personas: lista(ia.personas),
        compromisos: lista(ia.compromisos),
        compromisos_cumplidos: lista(ia.compromisos_cumplidos).map(Number).filter((id) => abiertos.has(id)),
      },
    },
    pairedItem: i,
  };
});
